import React, { useState } from 'react';

const Projects = () => {
  const [activeFilter, setActiveFilter] = useState('All');

  const projects = [
    {
      id: 1,
      title: 'Heritage Coffee Brand',
      category: 'Brand Identity',
      year: '2024',
    },
    {
      id: 2,
      title: 'TechFlow Dashboard',
      category: 'UI/UX Design',
      year: '2024',
    },
    {
      id: 3,
      title: 'Artisan Bakery',
      category: 'Brand Identity',
      year: '2024',
    },
    {
      id: 4,
      title: 'Finance App',
      category: 'UI/UX Design',
      year: '2023',
    },
    {
      id: 5,
      title: 'Eco Packaging',
      category: 'Design',
      year: '2023',
    },
    {
      id: 6,
      title: 'Music Streaming',
      category: 'Development',
      year: '2023',
    },
    {
      id: 7,
      title: 'Travel Platform',
      category: 'UI/UX Design',
      year: '2022',
    },
    {
      id: 8,
      title: 'Health Tracker',
      category: 'Development',
      year: '2022',
    },
  ];

  const filters = ['All', 'Brand Identity', 'UI/UX Design', 'Development', 'Design'];

  const filteredProjects = activeFilter === 'All'
    ? projects
    : projects.filter(p => p.category === activeFilter);

  return (
    <div className="section" style={{ paddingTop: '140px' }}>
      <div className="container">
        {/* Header */}
        <div className="section-header">
          <p className="section-label">Portfolio</p>
          <h1>Selected Work</h1>
          <p className="section-description">
            A curated collection of projects spanning branding, design, and development.
          </p>
        </div>

        {/* Filter */}
        <div className="filter-group">
          {filters.map((filter) => (
            <button
              key={filter}
              className={`filter-btn ${activeFilter === filter ? 'active' : ''}`}
              onClick={() => setActiveFilter(filter)}
            >
              {filter}
            </button>
          ))}
        </div>

        {/* Projects Grid */}
        <div className="project-grid">
          {filteredProjects.map((project) => (
            <article key={project.id} className="project-card">
              <div className="project-card-image">
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)',
                    fontFamily: 'var(--font-mono)',
                    fontSize: 'var(--text-xs)',
                    color: '#52525b'
                  }}
                >
                  {project.category}
                </div>
              </div>
              <div className="project-card-content">
                <span className="project-card-category">
                  {project.category}
                </span>
                <h3 className="project-card-title">{project.title}</h3>
              </div>
              <div className="project-card-meta">
                <span className="project-card-year">{project.year}</span>
                <span style={{ color: 'var(--accent-primary)', fontSize: 'var(--text-sm)' }}>
                  View →
                </span>
              </div>
            </article>
          ))}
        </div>

        {/* Decorative Line */}
        <div className="gradient-line" style={{ margin: 'var(--space-20) 0' }} />

        {/* Collaboration CTA */}
        <div style={{ textAlign: 'center' }}>
          <p
            className="text-mono"
            style={{ color: 'var(--text-muted)', marginBottom: 'var(--space-4)' }}
          >
            Interested in collaborating?
          </p>
          <a
            href="mailto:hello@bellezaa.com"
            style={{
              fontSize: 'var(--text-2xl)',
              fontWeight: 700,
              color: 'var(--text-primary)',
            }}
          >
            hello@bellezaa.com
          </a>
        </div>
      </div>
    </div>
  );
};

export default Projects;
